def transform(grid):
    # Pattern illustrated by the demo is a fixed 5x3 motif. Each 3 marks
    # its top-left placement offset (-2,-1); the original motif is retained.
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    motif=[[1,1,0],[0,4,0],[0,1,5],[4,4,bg],[0,bg,bg]]
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==3:
                for dr in range(5):
                    for dc in range(3):
                        rr,cc=r-2+dr,c-1+dc
                        if 0<=rr<h and 0<=cc<w:
                            out[rr][cc]=motif[dr][dc]
    return out
